PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      employee_code TEXT UNIQUE NOT NULL,
      full_name TEXT NOT NULL,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      role TEXT DEFAULT 'employee',
      department TEXT,
      position TEXT,
      avatar_color TEXT DEFAULT '#4F46E5',
      avatar_initials TEXT,
      phone TEXT,
      salary REAL DEFAULT 0,
      bank_account TEXT,
      bank_name TEXT,
      is_active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    , employee_type TEXT DEFAULT 'NV', lifecycle_status TEXT DEFAULT 'Chờ tiếp nhận', birth_date TEXT, gender TEXT, national_id TEXT, home_address TEXT, emergency_contact_name TEXT, emergency_contact_phone TEXT, direct_manager_id INTEGER, work_location TEXT, contract_type TEXT, contract_start_date TEXT, contract_end_date TEXT, contract_signed_date TEXT, official_date TEXT, termination_date TEXT, allowance REAL DEFAULT 0, insurance_salary REAL DEFAULT 0, bank_account_holder TEXT, tax_code TEXT, social_insurance_number TEXT, insurance_hospital TEXT, avatar_url TEXT, national_id_document_url TEXT, degree_document_url TEXT, contract_document_url TEXT, personnel_decision_url TEXT, school_name TEXT, hire_date TEXT, probation_end_date TEXT, dependent_count INTEGER DEFAULT 0, national_id_expiry_date TEXT, updated_at TEXT, updated_by INTEGER, must_change_password INTEGER DEFAULT 0, profile_pending INTEGER DEFAULT 0);
CREATE TABLE sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      token TEXT UNIQUE NOT NULL,
      expires_at INTEGER NOT NULL,
      revoked INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE attendance (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      date TEXT NOT NULL,
      checkin_time TEXT,
      checkout_time TEXT,
      checkin_ip TEXT,
      checkout_ip TEXT,
      status TEXT DEFAULT 'present',
      work_hours REAL DEFAULT 0,
      note TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    , work_type TEXT DEFAULT 'office', shift TEXT DEFAULT 'full', expected_start TEXT, expected_end TEXT, late_minutes INTEGER DEFAULT 0, early_minutes INTEGER DEFAULT 0, registered INTEGER DEFAULT 0, source_batch_id INTEGER, auto_checkout INTEGER DEFAULT 0, checkin_location_id INTEGER, checkout_location_id INTEGER, checkin_distance_meters REAL, checkout_distance_meters REAL, checkin_accuracy_meters REAL, checkout_accuracy_meters REAL, checkin_verification_method TEXT, checkout_verification_method TEXT, checkin_lat REAL, checkin_lng REAL, checkout_lat REAL, checkout_lng REAL, checkin_geofence_status TEXT, checkout_geofence_status TEXT, checkin_requires_review INTEGER DEFAULT 0, checkin_review_status TEXT DEFAULT 'none', checkin_reviewed_by INTEGER, checkin_review_note TEXT, checkin_reviewed_at TEXT, checkout_requires_review INTEGER DEFAULT 0, checkout_review_status TEXT DEFAULT 'none', checkout_reviewed_by INTEGER, checkout_review_note TEXT, checkout_reviewed_at TEXT);
CREATE TABLE wifi_whitelist (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      wifi_name TEXT,
      ip_range TEXT,
      description TEXT,
      is_active INTEGER DEFAULT 1
    );
CREATE TABLE tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      description TEXT,
      assigned_to INTEGER,
      assigned_by INTEGER,
      department TEXT,
      date TEXT,
      due_date TEXT,
      status TEXT DEFAULT 'todo',
      priority TEXT DEFAULT 'normal',
      label_color TEXT DEFAULT '#6366F1',
      checkin_time TEXT,
      checkout_time TEXT,
      is_locked INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now','localtime')),
      updated_at TEXT DEFAULT (datetime('now','localtime'))
    , workspace_id INTEGER DEFAULT 1, team_project_id INTEGER, label_id INTEGER, group_id INTEGER, external_source TEXT, external_id TEXT, external_metadata TEXT, import_position INTEGER);
CREATE TABLE subtasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id INTEGER NOT NULL,
      title TEXT NOT NULL,
      is_done INTEGER DEFAULT 0,
      assigned_to INTEGER,
      due_date TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    , description TEXT);
CREATE TABLE task_followers (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id INTEGER NOT NULL,
      user_id INTEGER NOT NULL
    );
CREATE TABLE task_comments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id INTEGER NOT NULL,
      user_id INTEGER NOT NULL,
      content TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    );
CREATE TABLE task_activity (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id INTEGER NOT NULL,
      user_id INTEGER NOT NULL,
      action TEXT NOT NULL,
      detail TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    , project_id INTEGER, entity_type TEXT, entity_id INTEGER, entity_title TEXT, assignee_id INTEGER, assignee_name TEXT, actor_name TEXT);
CREATE TABLE invoices (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      invoice_number TEXT UNIQUE NOT NULL,
      user_id INTEGER NOT NULL,
      month INTEGER NOT NULL,
      year INTEGER NOT NULL,
      base_salary REAL DEFAULT 0,
      bonus REAL DEFAULT 0,
      allowance REAL DEFAULT 0,
      deduction REAL DEFAULT 0,
      tax REAL DEFAULT 0,
      insurance REAL DEFAULT 0,
      net_salary REAL DEFAULT 0,
      work_days INTEGER DEFAULT 0,
      absent_days INTEGER DEFAULT 0,
      late_days INTEGER DEFAULT 0,
      status TEXT DEFAULT 'draft',
      note TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    , standard_days INTEGER DEFAULT 0, paid_leave_days INTEGER DEFAULT 0, late_minutes INTEGER DEFAULT 0, early_leave_minutes INTEGER DEFAULT 0, missing_checkinout_days INTEGER DEFAULT 0, locked_at TEXT, locked_by INTEGER, locked_by_name TEXT, payroll_id INTEGER, issued_at TEXT, issued_by INTEGER, issued_by_name TEXT, employee_confirmed_at TEXT, review_requested_at TEXT, review_resolved_at TEXT, review_status TEXT DEFAULT 'none', review_reason TEXT, review_note TEXT, approved_overtime_minutes INTEGER DEFAULT 0, overtime_pay REAL DEFAULT 0);
CREATE TABLE settings (setting_key TEXT PRIMARY KEY, setting_value TEXT);
CREATE TABLE departments (
      id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT,
      name TEXT NOT NULL, manager TEXT, description TEXT
    , manager_id INTEGER);
CREATE TABLE employees (
      id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, code TEXT,
      name TEXT NOT NULL, department_id INTEGER, position TEXT,
      start_date TEXT, birthday TEXT, status TEXT DEFAULT 'active',
      salary REAL DEFAULT 0, phone TEXT, email TEXT
    );
CREATE TABLE leave_requests (
      id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT,
      employee_id INTEGER, type TEXT, start_date TEXT, end_date TEXT,
      reason TEXT, status TEXT DEFAULT 'pending'
    , current_approver TEXT, approval_level INTEGER DEFAULT 1, submitted_at TEXT, leave_session TEXT DEFAULT 'full', total_days REAL, handover_user_id INTEGER, handover_user_name TEXT, approval_flow TEXT, balance_reserved_days REAL DEFAULT 0);
CREATE TABLE candidates (
      id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, name TEXT,
      position TEXT, department_id INTEGER, apply_date TEXT, source TEXT,
      stage TEXT DEFAULT 'received', notes TEXT
    , cv_storage_key TEXT, cv_original_filename TEXT, cv_content_type TEXT, cv_byte_size INTEGER DEFAULT 0);
CREATE TABLE payroll (
      id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT,
      employee_id INTEGER, month TEXT, base_salary REAL DEFAULT 0,
      kpi_bonus REAL DEFAULT 0, allowance REAL DEFAULT 0,
      deduction REAL DEFAULT 0, employee_name TEXT, net_salary REAL DEFAULT 0, department TEXT, employee_code TEXT, data_status TEXT DEFAULT 'ready', data_warnings TEXT, source_synced_at TEXT, overtime_pay REAL DEFAULT 0, tax REAL DEFAULT 0, insurance REAL DEFAULT 0, work_days REAL DEFAULT 0, standard_days REAL DEFAULT 0, note TEXT,
      UNIQUE(user_id, employee_id, month)
    );
CREATE TABLE leave_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    paid_policy TEXT DEFAULT 'paid',
    deducts_annual_leave INTEGER DEFAULT 0,
    requires_evidence INTEGER DEFAULT 0,
    requires_bod_approval INTEGER DEFAULT 0,
    max_days INTEGER,
    is_active INTEGER DEFAULT 1,
    created_at TEXT DEFAULT (datetime('now','localtime')),
    updated_at TEXT DEFAULT (datetime('now','localtime'))
  , short_description TEXT, policy_description TEXT, notice_hours INTEGER, required_documents TEXT, requires_handover INTEGER DEFAULT 0, approval_flow TEXT);
CREATE TABLE payroll_batches (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      month TEXT UNIQUE NOT NULL,
      status TEXT DEFAULT 'draft',
      total_employees INTEGER DEFAULT 0,
      complete_employees INTEGER DEFAULT 0,
      missing_employees INTEGER DEFAULT 0,
      estimated_total REAL DEFAULT 0,
      created_by INTEGER,
      created_by_name TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime')),
      updated_at TEXT DEFAULT (datetime('now','localtime'))
    );
CREATE TABLE lifecycle_history (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, from_status TEXT, to_status TEXT NOT NULL, changed_by INTEGER, changed_by_name TEXT, reason TEXT, changed_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE task_workspaces (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  description TEXT,
  created_by INTEGER,
  created_at TEXT DEFAULT (datetime('now','localtime')),
  updated_at TEXT DEFAULT (datetime('now','localtime'))
);
CREATE TABLE task_projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER DEFAULT 1,
  name TEXT NOT NULL,
  code TEXT,
  type TEXT DEFAULT 'project',
  description TEXT,
  department TEXT,
  manager_id INTEGER,
  status TEXT DEFAULT 'active',
  start_date TEXT,
  end_date TEXT,
  created_by INTEGER,
  created_at TEXT DEFAULT (datetime('now','localtime')),
  updated_at TEXT DEFAULT (datetime('now','localtime'))
, external_source TEXT, external_id TEXT);
CREATE TABLE task_project_members (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  role TEXT DEFAULT 'member',
  added_by INTEGER,
  created_at TEXT DEFAULT (datetime('now','localtime'))
);
CREATE TABLE task_labels (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER DEFAULT 1,
  project_id INTEGER,
  name TEXT NOT NULL,
  code TEXT,
  color TEXT NOT NULL,
  description TEXT,
  is_active INTEGER DEFAULT 1,
  created_by INTEGER,
  created_at TEXT DEFAULT (datetime('now','localtime')),
  updated_at TEXT DEFAULT (datetime('now','localtime'))
);
CREATE TABLE task_groups (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  position INTEGER DEFAULT 0,
  color TEXT DEFAULT '#6366F1',
  is_archived INTEGER DEFAULT 0,
  created_by INTEGER,
  created_at TEXT DEFAULT (datetime('now','localtime')),
  updated_at TEXT DEFAULT (datetime('now','localtime'))
, external_source TEXT, external_id TEXT);
CREATE TABLE campaigns (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, name TEXT NOT NULL, type TEXT DEFAULT 'other', status TEXT DEFAULT 'planning', start_date TEXT, end_date TEXT, budget REAL DEFAULT 0, spent REAL DEFAULT 0, goal_reach INTEGER DEFAULT 0, goal_leads INTEGER DEFAULT 0, goal_conversions INTEGER DEFAULT 0, owner_name TEXT, description TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE eval_periods (id INTEGER PRIMARY KEY AUTOINCREMENT, month INTEGER NOT NULL, year INTEGER NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, created_by INTEGER, created_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), hr_note TEXT, hr_note_by TEXT, hr_note_at TEXT, UNIQUE(month, year));
CREATE TABLE evaluations (id INTEGER PRIMARY KEY AUTOINCREMENT, period_id INTEGER NOT NULL, user_id INTEGER NOT NULL, mentor_id INTEGER, mentor_name TEXT, department_head_id INTEGER, department_head_name TEXT, status TEXT DEFAULT 'DRAFT', window_override INTEGER DEFAULT 0, mentor_scores TEXT, mentor_comments TEXT, mentor_submitted_at TEXT, department_scores TEXT, department_comments TEXT, department_submitted_at TEXT, employee_confirmed_at TEXT, employee_revision_reason TEXT, employee_revision_evidence TEXT, employee_revision_at TEXT, ceo_revision_reason TEXT, ceo_revision_at TEXT, final_approved_score REAL, final_approved_comment TEXT, final_score_before_adjust REAL, final_adjust_reason TEXT, approved_by INTEGER, approved_by_name TEXT, approved_at TEXT, hr_received_by INTEGER, hr_received_by_name TEXT, hr_received_at TEXT, locked_by INTEGER, locked_by_name TEXT, locked_at TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')), UNIQUE(period_id, user_id));
CREATE TABLE evaluation_history (id INTEGER PRIMARY KEY AUTOINCREMENT, evaluation_id INTEGER NOT NULL, from_status TEXT, to_status TEXT NOT NULL, changed_by INTEGER, changed_by_name TEXT, note TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE payroll_adjustments (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_id INTEGER NOT NULL, payroll_id INTEGER, month TEXT NOT NULL, type TEXT NOT NULL, source TEXT NOT NULL, source_ref TEXT UNIQUE, amount REAL DEFAULT 0, score_delta REAL DEFAULT 0, reason TEXT NOT NULL, status TEXT DEFAULT 'suggested', created_by INTEGER, created_by_name TEXT, approved_by INTEGER, approved_by_name TEXT, approved_at TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')), violation_date TEXT, policy_month TEXT);
CREATE TABLE invoice_review_requests (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      invoice_id INTEGER NOT NULL,
      user_id INTEGER NOT NULL,
      category TEXT NOT NULL,
      message TEXT NOT NULL,
      requested_amount REAL DEFAULT 0,
      status TEXT DEFAULT 'open',
      handled_by INTEGER,
      handled_by_name TEXT,
      handled_note TEXT,
      handled_at TEXT,
      created_at TEXT DEFAULT (datetime('now','localtime')),
      updated_at TEXT DEFAULT (datetime('now','localtime'))
    );
CREATE TABLE invoice_history (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL, from_status TEXT, to_status TEXT, changed_by INTEGER, changed_by_name TEXT, note TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE leave_approval_history (id INTEGER PRIMARY KEY AUTOINCREMENT, leave_request_id INTEGER NOT NULL, approval_level INTEGER NOT NULL, actor_id INTEGER, actor_name TEXT, action TEXT NOT NULL, note TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE overtime_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, attendance_id INTEGER NOT NULL UNIQUE, user_id INTEGER NOT NULL, work_date TEXT NOT NULL, shift_end_time TEXT NOT NULL, checkout_time TEXT NOT NULL, requested_minutes INTEGER NOT NULL, approved_minutes INTEGER, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reviewer_id INTEGER, reviewer_name TEXT, review_note TEXT, reviewed_at TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE company_holidays (id INTEGER PRIMARY KEY AUTOINCREMENT, holiday_date TEXT NOT NULL UNIQUE, name TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE employee_kpi_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, employee_id INTEGER NOT NULL, month INTEGER NOT NULL, year INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', created_by INTEGER, created_by_name TEXT, submitted_at TEXT, reviewed_by INTEGER, reviewed_by_name TEXT, reviewed_at TEXT, review_note TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')), UNIQUE(employee_id, month, year));
CREATE TABLE employee_kpi_items (id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL, criterion_code TEXT NOT NULL, title TEXT NOT NULL, description TEXT, unit TEXT NOT NULL DEFAULT 'đơn vị', target_value REAL NOT NULL, actual_value REAL, weight_percent REAL NOT NULL, evidence_url TEXT, affects_group1 INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')), actual_text TEXT, manual_score REAL, review_note TEXT, requires_evidence INTEGER NOT NULL DEFAULT 0);
CREATE TABLE kpi_templates (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, created_by INTEGER, created_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE kpi_template_items (id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL, criterion_code TEXT NOT NULL, title TEXT NOT NULL, description TEXT, unit TEXT NOT NULL DEFAULT 'đơn vị', target_value REAL NOT NULL, weight_percent REAL DEFAULT 0, affects_group1 INTEGER NOT NULL DEFAULT 1, requires_evidence INTEGER NOT NULL DEFAULT 0);
CREATE TABLE evaluation_kpi_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, evaluation_id INTEGER NOT NULL, criterion_code TEXT NOT NULL, achievement_percent REAL NOT NULL, automatic_score REAL NOT NULL, details_json TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now','localtime')), UNIQUE(evaluation_id, criterion_code));
CREATE TABLE employee_kpi_evidence (
    id INTEGER PRIMARY KEY AUTOINCREMENT, kpi_item_id INTEGER NOT NULL, label TEXT NOT NULL DEFAULT '', url TEXT NOT NULL,
    created_by INTEGER, created_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')),
    updated_by INTEGER, updated_by_name TEXT, updated_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE employee_kpi_evidence_audit (
    id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL, kpi_item_id INTEGER NOT NULL,
    action TEXT NOT NULL, old_value_json TEXT, new_value_json TEXT,
    changed_by INTEGER, changed_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE employee_kpi_approval_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL, employee_id INTEGER NOT NULL, month INTEGER NOT NULL, year INTEGER NOT NULL,
    snapshot_json TEXT NOT NULL, approved_by INTEGER, approved_by_name TEXT, approved_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(plan_id)
  );
CREATE TABLE employee_kpi_approval_snapshots_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT, plan_id INTEGER NOT NULL, employee_id INTEGER NOT NULL, month INTEGER NOT NULL, year INTEGER NOT NULL,
    snapshot_json TEXT NOT NULL, approved_by INTEGER, approved_by_name TEXT, approved_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE employee_documents (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    category TEXT NOT NULL,
    title TEXT,
    original_filename TEXT NOT NULL,
    content_type TEXT NOT NULL,
    byte_size INTEGER NOT NULL DEFAULT 0,
    storage_key TEXT NOT NULL UNIQUE,
    expires_on TEXT,
    uploaded_by INTEGER,
    uploaded_by_name TEXT,
    uploaded_at TEXT DEFAULT (datetime('now','localtime')),
    deleted_at TEXT,
    deleted_by INTEGER,
    deleted_by_name TEXT
  );
CREATE TABLE employee_profile_audit (
    id TEXT PRIMARY KEY,
    change_set_id TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    action TEXT NOT NULL,
    field_group TEXT NOT NULL,
    field_name TEXT NOT NULL,
    old_value TEXT,
    new_value TEXT,
    changed_by INTEGER,
    changed_by_name TEXT,
    changed_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE payroll_change_log (id INTEGER PRIMARY KEY AUTOINCREMENT, payroll_id INTEGER NOT NULL, changed_by INTEGER NOT NULL, changed_by_name TEXT, change_note TEXT NOT NULL, before_data TEXT NOT NULL, after_data TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE overtime_forms (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,period_month TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',source TEXT NOT NULL DEFAULT 'employee',source_batch_id INTEGER,review_note TEXT,reviewer_id INTEGER,reviewer_name TEXT,reviewed_at TEXT,submitted_at TEXT,created_at TEXT DEFAULT (datetime('now','localtime')),updated_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE overtime_form_items (id INTEGER PRIMARY KEY AUTOINCREMENT,form_id INTEGER NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,requested_minutes INTEGER NOT NULL,approved_minutes INTEGER,reason TEXT NOT NULL,time_category TEXT NOT NULL DEFAULT 'workday',created_at TEXT DEFAULT (datetime('now','localtime')),updated_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE attendance_import_batches (id INTEGER PRIMARY KEY AUTOINCREMENT,source_name TEXT NOT NULL,period_month TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'preview',created_by INTEGER NOT NULL,created_by_name TEXT,created_at TEXT DEFAULT (datetime('now','localtime')),committed_at TEXT);
CREATE TABLE attendance_import_rows (id INTEGER PRIMARY KEY AUTOINCREMENT,batch_id INTEGER NOT NULL,source_key TEXT NOT NULL,employee_code TEXT NOT NULL,work_date TEXT,attendance_id INTEGER,outcome TEXT NOT NULL,detail TEXT,created_at TEXT DEFAULT (datetime('now','localtime')),UNIQUE(batch_id,source_key));
CREATE TABLE asset_handovers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, asset_name TEXT NOT NULL, asset_type TEXT, platform TEXT, link TEXT, credential_enc TEXT, responsible_name TEXT, mentor_id INTEGER, mentor_name TEXT, status TEXT DEFAULT 'active', note TEXT, confirmed_by INTEGER, confirmed_at TEXT, expected_handover_date TEXT, created_at TEXT DEFAULT (datetime('now','localtime')), updated_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE asset_credential_log (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, viewed_by INTEGER, viewed_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE asset_handover_history (id INTEGER PRIMARY KEY AUTOINCREMENT, asset_id INTEGER NOT NULL, action TEXT NOT NULL, actor_id INTEGER, actor_name TEXT, detail TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE payroll_line_change_log (id INTEGER PRIMARY KEY AUTOINCREMENT, payroll_id INTEGER NOT NULL, line_key TEXT NOT NULL, line_label TEXT NOT NULL, before_value REAL NOT NULL, after_value REAL NOT NULL, change_note TEXT NOT NULL, changed_by INTEGER NOT NULL, changed_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE leave_balances (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, leave_type_code TEXT NOT NULL, balance_year INTEGER NOT NULL, available_days REAL NOT NULL DEFAULT 0, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT DEFAULT (datetime('now','localtime')), UNIQUE(user_id,leave_type_code,balance_year));
CREATE TABLE leave_balance_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, leave_type_code TEXT NOT NULL, balance_year INTEGER NOT NULL, leave_request_id INTEGER, delta_days REAL NOT NULL, entry_type TEXT NOT NULL, note TEXT, created_by INTEGER, created_by_name TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE leave_request_documents (id TEXT PRIMARY KEY, leave_request_id INTEGER, owner_id INTEGER NOT NULL, original_filename TEXT NOT NULL, content_type TEXT NOT NULL, byte_size INTEGER NOT NULL, storage_key TEXT NOT NULL UNIQUE, required_label TEXT, uploaded_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE conversations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL DEFAULT 'direct',
    name TEXT,
    team_id INTEGER,
    project_id INTEGER,
    created_by INTEGER NOT NULL,
    created_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE conversation_members (
    conversation_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    role TEXT DEFAULT 'member',
    last_read_message_id INTEGER DEFAULT 0,
    notification_level TEXT DEFAULT 'all',
    joined_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(conversation_id, user_id)
  );
CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id INTEGER NOT NULL,
    sender_id INTEGER NOT NULL,
    content TEXT,
    reply_to_id INTEGER,
    thread_root_id INTEGER,
    task_id INTEGER,
    edited_at TEXT,
    deleted_at TEXT,
    created_at TEXT DEFAULT (datetime('now','localtime'))
  , message_type TEXT NOT NULL DEFAULT 'text');
CREATE TABLE message_attachments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    message_id INTEGER NOT NULL,
    type TEXT NOT NULL DEFAULT 'file',
    file_name TEXT NOT NULL,
    file_size INTEGER,
    mime_type TEXT,
    storage_key TEXT NOT NULL,
    width INTEGER,
    height INTEGER,
    created_at TEXT DEFAULT (datetime('now','localtime'))
  );
CREATE TABLE message_reactions (
    message_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    emoji TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(message_id, user_id, emoji)
  );
CREATE TABLE message_reads (
    message_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    read_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(message_id, user_id)
  );
CREATE TABLE message_mentions (
    message_id INTEGER NOT NULL,
    mentioned_user_id INTEGER NOT NULL,
    mentioned_by INTEGER NOT NULL,
    created_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(message_id, mentioned_user_id)
  );
CREATE TABLE pinned_messages (
    conversation_id INTEGER NOT NULL,
    message_id INTEGER NOT NULL,
    pinned_by INTEGER NOT NULL,
    created_at TEXT DEFAULT (datetime('now','localtime')),
    UNIQUE(conversation_id, message_id)
  );
CREATE TABLE message_all_mentions (message_id INTEGER PRIMARY KEY, mentioned_by INTEGER NOT NULL, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE chat_polls (message_id INTEGER PRIMARY KEY, question TEXT NOT NULL, allows_multiple INTEGER NOT NULL DEFAULT 1, is_closed INTEGER NOT NULL DEFAULT 0, closed_by INTEGER, closed_at TEXT, created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE chat_poll_options (id INTEGER PRIMARY KEY AUTOINCREMENT,message_id INTEGER NOT NULL,option_text TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE chat_poll_votes (option_id INTEGER NOT NULL,user_id INTEGER NOT NULL,created_at TEXT DEFAULT (datetime('now','localtime')),UNIQUE(option_id,user_id));
CREATE TABLE chat_events (message_id INTEGER PRIMARY KEY,title TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT,description TEXT,location TEXT,meeting_url TEXT,cancelled_at TEXT,cancelled_by INTEGER,created_at TEXT DEFAULT (datetime('now','localtime')));
CREATE TABLE chat_event_attendees (message_id INTEGER NOT NULL,user_id INTEGER NOT NULL,response TEXT NOT NULL DEFAULT 'invited',responded_at TEXT,UNIQUE(message_id,user_id));
CREATE TABLE attendance_locations (
      id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT, address TEXT,
      latitude REAL NOT NULL, longitude REAL NOT NULL, radius_meters INTEGER NOT NULL DEFAULT 100,
      max_accuracy_meters INTEGER NOT NULL DEFAULT 100, is_active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_attendance_user_date ON attendance(user_id,date);
CREATE INDEX idx_tasks_assigned_to ON tasks(assigned_to);
CREATE INDEX idx_tasks_status_due ON tasks(status,due_date);
CREATE INDEX idx_leave_requests_type ON leave_requests(type);
CREATE UNIQUE INDEX idx_departments_name_ci ON departments(lower(name));
CREATE INDEX idx_tasks_project ON tasks(team_project_id);
CREATE INDEX idx_tasks_label ON tasks(label_id);
CREATE INDEX idx_task_project_members_project_user ON task_project_members(project_id,user_id);
CREATE INDEX idx_task_labels_project_active ON task_labels(project_id,is_active);
CREATE INDEX idx_tasks_group ON tasks(group_id);
